CREATE COLUMN TABLE "TEST_AP"."OUQR" ("IntrnalKey" INTEGER CS_INT NOT NULL , "QCategory" INTEGER CS_INT NOT NULL , "QName" NVARCHAR(100) NOT NULL , "QString" NCLOB MEMORY THRESHOLD 1000, "QType" NVARCHAR(1) DEFAULT 'W', "ColumnSize" NVARCHAR(100), "DBType" INTEGER CS_INT, "QLastDate" LONGDATE CS_LONGDATE, "QLastTime" SMALLINT CS_INT, "Xslt" NCLOB MEMORY THRESHOLD 1000, PRIMARY KEY ("IntrnalKey", "QCategory")) UNLOAD PRIORITY 0  AUTO MERGE ;
CREATE UNIQUE INDEX "OUQR_QNAME_K" ON "TEST_AP"."OUQR" ( "QName" ASC, "QCategory" ASC )